head.script:
scwin.chrgTpCdArr = [];

scwin.onpageload = function() {
    scwin.corpUsrTpCd = $c.session.info("corpUsrTpCd");

    //TODO : 메뉴공통 include 하기 전까지 사용
    const menuInfo = $c.data.getParameter("menuInfo");
    if(menuInfo.menuNm == "신종증권공시담당자정보") {
       txt_menuNm.setValue("신종증권공시담당자정보"); 
    }

    //[화면통폐합] 공시담당자 유형에 따른 폼 변경
    scwin.fn_initForm();

    $c.sbm.execute(sbm_SelectChrg);

    //로그인한 법인의 담당자구분코드 정보 조회
    $c.sbm.execute(sbm_SelectChrgTpCd);

};


/// EVENT ///

/**
 * 신고서제출하기 버튼 클릭하여 화면이동
 * @DESC : 공시제출 > 새로만들기 > 보고서검색에 해당 관련 보고서 검색해서 내역 조회
 */
scwin.btn_dsclInsert_onclick = function (e) {
    const moveUrl = "/ui/dis/submission/JLDFIL00000.xml";
    let param = {};
    param.searchScope = "2";
    param.tabDiv = "search";
    param.isAllEdit = "true";
    param.formKorNm = "신규지정";

    $c.win.moveUrl(moveUrl, param);
};

/**
 * 공시교육일정 등 안내 버튼 클릭하여 팝업 오픈
 */
scwin.btn_eduSchdlView_onclick = function (e) {
    const thisYear = $p.getCurrentServerDate('yyyy');
    const data = {thisYear: thisYear};
    const options = {
        id: "EduSchdlViewPop",
        //title: true,
        //popupName: "교육일정 및 안내",
        type: "browserPopup", //browserPopup, pageFramePopup
        width: "800px",        
        height: "650px",
        resizable: true
    };
    $c.win.openPopup("/ui/dis/account/JLDFIL00356.xml", options, data);
};

/**
 * 이메일 도메인 선택
 */
scwin.sel_email_onviewchange = function (info) {
	const domain = info.newValue;
    const idx = this.getUserData("userData1");
    const iptObj = $p.getComponentById("ipt_email2_"+idx);
    if(iptObj) {
        iptObj.setValue(domain);
    }
};

/**
 * 우편번호 버튼 클릭
 */
scwin.btn_popZipCode_onclick = function (e) {
    let idx = this.getUserData("userData1");
	scwin.fn_popZipCode(idx);
};

/**
 * 교육이수내역보기 버튼 클릭하여 팝업 오픈
 */
scwin.btn_eduCompltListView_onclick = function (e) {
    let idx = this.getUserData("userData1");
    let chrgTpCd = ""; //담당자구분코드
    let chrgNm = ""; //담당자명

    if(idx == "1") {
        chrgTpCd = dma_CorpDisclsChrg1.get("chrgTpCd");
        chrgNm = dma_CorpDisclsChrg1.get("chrgNm");
    } else if(idx == "2") {
        chrgTpCd = dma_CorpDisclsChrg2.get("chrgTpCd");
        chrgNm = dma_CorpDisclsChrg2.get("chrgNm");
    } else if(idx == "3") {
        chrgTpCd = dma_CorpDisclsChrg3.get("chrgTpCd");
        chrgNm = dma_CorpDisclsChrg3.get("chrgNm");
    } else if(idx == "4") {
        chrgTpCd = dma_CorpDisclsChrg4.get("chrgTpCd");
        chrgNm = dma_CorpDisclsChrg4.get("chrgNm");
    } else if(idx == "5") {
        chrgTpCd = dma_CorpDisclsChrg5.get("chrgTpCd");
        chrgNm = dma_CorpDisclsChrg5.get("chrgNm");

    }

    scwin.fn_eduCompltListView(idx, chrgTpCd, chrgNm);
};

/**
 * 재등록 버튼 클릭
 */
scwin.btn_insert_onclick = function (e) {
    const idx = this.getUserData("userData1");
    scwin.fn_modify("insert", idx);
};

/**
 * 수정 버튼 클릭
 */
scwin.btn_update_onclick = function (e) {
    const idx = this.getUserData("userData1");
    scwin.fn_modify("update", idx);
};

/**
 * 삭제 버튼 클릭
 */
scwin.btn_delete_onclick = function (e) {
    const idx = this.getUserData("userData1");
    scwin.fn_delete(idx);
};


/// SUBMISSION ///

scwin.sbm_SelectChrg_submitdone = function (e) {
    const res = e.responseJSON;
    const body = res.body;

    //1.공시책임자 정보관리
    if(body.corpDisclsChrg1) {
        dma_CorpDisclsChrg1.setJSON(body.corpDisclsChrg1);
        scwin.fn_initEditView(1);
    } else {
        //재등록 가능한 경우만 성명 입력 활성화(ETF, 채권, ELW, ETN)
        if(!(scwin.corpUsrTpCd == "11" || scwin.corpUsrTpCd == "21" || scwin.corpUsrTpCd == "61" || scwin.corpUsrTpCd == "63" || scwin.corpUsrTpCd == "1C")) {
            $c.stf.showObj($p.getComponentById("grp_i_chrgNm_1"), true);
            $c.stf.showObj($p.getComponentById("grp_u_chrgNm_1"), false);
        }
    }

    //2.공시담당자(정) 정보관리
    if(body.corpDisclsChrg2) {
        dma_CorpDisclsChrg2.setJSON(body.corpDisclsChrg2);
        scwin.fn_initEditView(2);
    } else {
        //재등록 가능한 경우만 성명 입력 활성화(ETF, 채권, ELW, ETN)
        if(!(scwin.corpUsrTpCd == "11" || scwin.corpUsrTpCd == "21" || scwin.corpUsrTpCd == "61" || scwin.corpUsrTpCd == "63" || scwin.corpUsrTpCd == "1C")) {
            $c.stf.showObj($p.getComponentById("grp_i_chrgNm_2"), true);
            $c.stf.showObj($p.getComponentById("grp_u_chrgNm_2"), false);
        }
    }

    //3.공시담당자(부) 정보관리
    if(body.corpDisclsChrg3) {
        dma_CorpDisclsChrg3.setJSON(body.corpDisclsChrg3);
        scwin.fn_initEditView(3);
    } else {
        //재등록 가능한 경우만 성명 입력 활성화(ETF, 채권, ELW, ETN)
        if(!(scwin.corpUsrTpCd == "11" || scwin.corpUsrTpCd == "21" || scwin.corpUsrTpCd == "61" || scwin.corpUsrTpCd == "63" || scwin.corpUsrTpCd == "1C")) {
            $c.stf.showObj($p.getComponentById("grp_i_chrgNm_3"), true);
            $c.stf.showObj($p.getComponentById("grp_u_chrgNm_3"), false);
        }
    }

    //4.공시담당자 보조자
    if(body.corpDisclsChrg4) {
        dma_CorpDisclsChrg4.setJSON(body.corpDisclsChrg4);
        scwin.fn_initEditView(4);
    } else {
        //재등록 가능한 경우만 성명 입력 활성화
        if(scwin.corpUsrTpCd == "21") { //코스닥 공시대리인
            $c.stf.showObj($p.getComponentById("grp_i_chrgNm_4"), true);
            $c.stf.showObj($p.getComponentById("grp_u_chrgNm_4"), false);
        }
    }

    //5.공시대리인 정보관리
    if(body.corpDisclsChrg5) {
        dma_CorpDisclsChrg5.setJSON(body.corpDisclsChrg5);
        scwin.fn_initEditView(5);
    }

    //채권담당자 표시
    if(body.bndCorpDisclsChrg1) {
        let bondChrgNm = body.bndCorpDisclsChrg1.chrgNm;
        txt_bondDisclsChrgNm_1.setValue('<font color="blue">* 당해법인 채권공시책임자 : '+bondChrgNm+'</font> (* 채권공시문의 : 채권시장부 02-3774-8682~3)');
    }
    if(body.bndCorpDisclsChrg2) {
        let bondChrgNm = body.bndCorpDisclsChrg2.chrgNm;
        txt_bondDisclsChrgNm_2.setValue('<font color="blue">* 당해법인 채권공시담당자 : '+bondChrgNm+'</font> (* 채권공시문의 : 채권시장부 02-3774-8682~3)');
    }
    if(body.bndCorpDisclsChrg3) {
        let bondChrgNm = body.bndCorpDisclsChrg3.chrgNm;
        txt_bondDisclsChrgNm_3.setValue('<font color="blue">* 당해법인 채권공시실무자 : '+bondChrgNm+'</font> (* 채권공시문의 : 채권시장부 02-3774-8682~3)');
    }
};

scwin.sbm_UpsertDisclsInfo_submitdone = function (e) {
    const res = e.responseJSON;
    if(dma_CorpDisclsChrgReq.get("chrgNm") == res.body) {
	    alert('요청하신 작업을 완료하였습니다.');
    } else {
        alert('현재 공시담당자 정보와 일치하지 않아 수정할 수 없습니다.\n다시 입력해주시기 바랍니다.');
    }
    $p.reinitialize();
};

scwin.sbm_DeleteDisclsInfo_submitdone = function (e) {
    const res = e.responseJSON;
    if(dma_CorpDisclsChrgReq.get("chrgTpCd") == res.body) {
	    alert('요청하신 작업을 완료하였습니다.');
    }
    $p.reinitialize();
};

scwin.sbm_SelectChrgTpCd_submitdone = function (e) {
    const res = e.responseJSON;
    scwin.chrgTpCdArr = res.body;
};


/// FUNCTION ///

/**
 * 공시담당자 유형에 따른 폼 변경
 */
scwin.fn_initForm = function () {
    //공시담당자 유형 표출
    if(scwin.corpUsrTpCd == "11") { //유가
        txt_title_1.setValue("공시책임자");
        txt_title_2.setValue("공시담당자(정)");
        txt_title_3.setValue("공시담당자(부)");
        txt_title_4.setValue("공시담당보조자");
        txt_title_5.setValue("공시대리인");

        //교육이수정보 영역 표시
        $c.stf.showObj(grp_eduInfo_1, true);
        $c.stf.showObj(grp_eduInfo_2, true);
        $c.stf.showObj(grp_eduInfo_3, true);
        $c.stf.showObj(grp_eduInfo_4, true);
        $c.stf.showObj(grp_eduInfo_5, true);

    } else if(scwin.corpUsrTpCd == "21") { //코스닥
        txt_title_1.setValue("공시책임자");
        txt_title_2.setValue("공시담당자");
        txt_title_3.setValue("공시실무자");
        txt_title_4.setValue("공시대리인");

        //사용 안하는 영역
        $c.stf.showObj(grp_title_5, false);
        $c.stf.showObj(grp_corpDisclsChrg_5, false);

        //담당자 증시변경 가능한 유형 ------------------------------------
        //삭제버튼 : 코스닥 공시대리인
        $c.stf.showObj(btn_insert_4, true);
        $c.stf.showObj(btn_delete_4, true);

        //문구(삭제 가능한 경우만 재등록 가능)
        $p.getComponentById("txt_info_chrgNm_4").setValue("* 담당자를 변경하려면 [삭제] 후 [재등록]하시기 바랍니다.");

        //지정일(수정X, 재등록 시에만 활성화)
        $c.stf.showObj(grp_view_chrgDesignDd_4, false);
        $c.stf.showObj(grp_edit_chrgDesignDd_4, true);

        //---------------------------------------------------------------

    } else if(scwin.corpUsrTpCd == "61") { //코넥스
        txt_title_1.setValue("공시책임자");
        txt_title_2.setValue("공시담당자");
        txt_title_3.setValue("공시실무자");
        txt_title_4.setValue("지정자문인 업무담당자");

        //사용 안하는 영역
        $c.stf.showObj(grp_title_5, false);
        $c.stf.showObj(grp_corpDisclsChrg_5, false);

        //코넥스 회원이 조회하는 지정자문인 업무담당자 정보관리에 대해서는 수정 버튼 숨김 처리
        $c.stf.showObj($p.getComponentById("btn_update_4"), false);

    } else if(scwin.corpUsrTpCd == "63") { //지정자문인
        txt_title_1.setValue("업무책임자");
        txt_title_2.setValue("업무담당자");

        //사용 안하는 영역
        $c.stf.showObj(grp_title_3, false);
        $c.stf.showObj(grp_corpDisclsChrg_3, false);
        $c.stf.showObj(grp_title_4, false);
        $c.stf.showObj(grp_corpDisclsChrg_4, false);
        $c.stf.showObj(grp_title_5, false);
        $c.stf.showObj(grp_corpDisclsChrg_5, false);

    } else if(scwin.corpUsrTpCd == "1C") { //신종증권공시담당자정보
        txt_title_1.setValue("신종증권 공시책임자");
        txt_title_2.setValue("신종증권 공시담당자(정)");
        txt_title_3.setValue("신종증권 공시담당자(부)");
        txt_title_4.setValue("신종증권 공시대리인(정)");
        txt_title_5.setValue("신종증권 공시대리인(부)");

    } else { //ETF, 채권, ELW, ETN
        txt_title_1.setValue("공시책임자");
        txt_title_2.setValue("공시담당자(정)");
        txt_title_3.setValue("공시담당자(부)");

        //사용 안하는 영역
        $c.stf.showObj(grp_title_4, false);
        $c.stf.showObj(grp_corpDisclsChrg_4, false);
        $c.stf.showObj(grp_title_5, false);
        $c.stf.showObj(grp_corpDisclsChrg_5, false);

        //담당자 증시변경 가능한 유형 ------------------------------------
        //삭제버튼(삭제 가능한 경우만 재등록 가능)
        $c.stf.showObj(btn_insert_1, true);
        $c.stf.showObj(btn_insert_2, true);
        $c.stf.showObj(btn_insert_3, true);
        $c.stf.showObj(btn_delete_1, true);
        $c.stf.showObj(btn_delete_2, true);
        $c.stf.showObj(btn_delete_3, true);

        //문구(삭제 가능한 경우만 재등록 가능)
        $p.getComponentById("txt_info_chrgNm_1").setValue("* 담당자를 변경하려면 [삭제] 후 [재등록]하시기 바랍니다.");
        $p.getComponentById("txt_info_chrgNm_2").setValue("* 담당자를 변경하려면 [삭제] 후 [재등록]하시기 바랍니다.");
        $p.getComponentById("txt_info_chrgNm_3").setValue("* 담당자를 변경하려면 [삭제] 후 [재등록]하시기 바랍니다.");

        //지정일
        $c.stf.showObj(grp_view_chrgDesignDd_1, false);
        $c.stf.showObj(grp_edit_chrgDesignDd_1, true);
        $c.stf.showObj(grp_view_chrgDesignDd_2, false);
        $c.stf.showObj(grp_edit_chrgDesignDd_2, true);
        $c.stf.showObj(grp_view_chrgDesignDd_3, false);
        $c.stf.showObj(grp_edit_chrgDesignDd_3, true);

        //---------------------------------------------------------------
    }

    //안내문구 변경
    if(scwin.corpUsrTpCd == "11" || scwin.corpUsrTpCd == "21" || scwin.corpUsrTpCd == "61" || scwin.corpUsrTpCd == "1C") {
        // 유가/코스닥/코넥스
        // 신종증권
        $c.stf.showObj(grp_info_1, true);
        $c.stf.showObj(btn_dsclInsert, true);
    } else if(scwin.corpUsrTpCd == "63") {
        // 지정자문인의 경우에만 표시
        $c.stf.showObj(grp_info_3_1, true);
        $c.stf.showObj(grp_info_3_2, true);
    } else {
        // 채권/ETF/ELW/ETN의 경우에만 표시
        $c.stf.showObj(grp_info_4_1, true);
        $c.stf.showObj(grp_info_4_2, true);
    }

    // 유가의 경우에만 추가로 표시
    if(scwin.corpUsrTpCd == "11") {
        $c.stf.showObj(grp_info_2_1, true);
        $c.stf.showObj(grp_info_2_2, true);
        $c.stf.showObj(btn_eduSchdlView, true);
    }
};

/**
 * 수정화면 초기값 세팅
 */
scwin.fn_initEditView = function (idx) {
    //이메일
    let emailObj = $p.getComponentById("ipt_email_"+idx);
    let email = emailObj.getValue();

    let email_1_Obj = $p.getComponentById("ipt_email1_"+idx);
    let email_2_Obj = $p.getComponentById("ipt_email2_"+idx);
    email_1_Obj.setValue(scwin.fn_emailFormat(email));
    email_2_Obj.setValue(scwin.fn_emailFormatDomain(email));

    //지정일
    let chrgDesignDdObj = $p.getComponentById("ipt_chrgDesignDd_"+idx);
    let dateArr = scwin.fn_getDateSplit(chrgDesignDdObj.getValue());
    if(dateArr && dateArr.yyyy && dateArr.mm && dateArr.dd) {
        $p.getComponentById("ipt_yyyy_"+idx).setValue(dateArr.yyyy);
        $p.getComponentById("ipt_mm_"+idx).setValue(dateArr.mm);
        $p.getComponentById("ipt_dd_"+idx).setValue(dateArr.dd);
    }

    //수정버튼 영역 표시
    $c.stf.showObj($p.getComponentById("grp_u_trigger_"+idx), true);
    $c.stf.showObj($p.getComponentById("grp_i_trigger_"+idx), false);

    //지정일(수정X, 재등록 시에만 활성화)
    $c.stf.showObj($p.getComponentById("grp_view_chrgDesignDd_"+idx), true);
    $c.stf.showObj($p.getComponentById("grp_edit_chrgDesignDd_"+idx), false);
};

/**
 * 우편번호 검색
 */
scwin.fn_popZipCode = function (idx) {
    const options = {
        id: "ZipWinPop",
        type: "browserPopup",
        width: "650px",        
        height: "720px",
        resizable: true
    };
    const param = {
        "data": {"idx": idx},
        "callbackFn": "scwin.fn_popZipCodeCallback"
    };
    $c.win.openPopup("/ui/dis/common/popup_roadZipcode.xml", options, param);

};

/**
 * 우편번호 검색 콜백함수
 */
scwin.fn_popZipCodeCallback = function (result) {
    const idx = result.req.idx;
    const zipcdObj = $p.getComponentById("ipt_locZipcd_"+idx);
    const addrObj = $p.getComponentById("ipt_locAddr_"+idx);
    const dtlAddrObj = $p.getComponentById("ipt_locDtlAddr_"+idx);

    zipcdObj.setValue(result.zipNo);
    addrObj.setValue(result.addr);
    dtlAddrObj.setValue("");
};

/**
 * 교육이수내역보기 팝업 오픈
 */
scwin.fn_eduCompltListView = function (i, chrgTpCd, chrgNm) {
    let chrgGb = ""; 
    if(!chrgTpCd || !chrgNm) {
        switch(i) {
            case '1' : chrgGb = "공시책임자";  	 break;
            case '2' : chrgGb = "공시담당자(정)";  break;
            case '3' : chrgGb = "공시담당자(부)";  break;
            case '4' : chrgGb = "공시담당 보조자";  break;
            case '5' : chrgGb = "공시대리인";  	 break;
        }

        alert("등록된 " + chrgGb + "가 없습니다.");
        return false;
    } else {
        const data = {
        "chrgTpCd": chrgTpCd,
        "chrgNm": chrgNm
        };
        const options = {
            id: "EduCompltListViewPop",
            type: "browserPopup",
            width: "1030px",        
            height: "500px",
            resizable: true
        };
        $c.win.openPopup("/ui/dis/account/JLDFIL00357.xml", options, data);
    }        
};



/**
 * 재등록 및 수정
 */
scwin.fn_modify = function (type, idx) {
    //const grpObj = $p.getComponentById("grp_corpDisclsChrg_"+idx);

    const obj_chrgNm = $p.getComponentById("ipt_chrgNm_"+idx);
    const obj_jobtitlNm = $p.getComponentById("ipt_jobtitlNm_"+idx);
