/**
 * 날짜포맷
 * @DESC : yyyyMMdd -> yyyy년 MM월 dd일
 */
scwin.fn_dateFormat = function (str) {
    if(str && str.length == 8) {
        let yyyy = str.substring(0, 4);
        let mm = str.substring(4, 6);
        let dd = str.substring(6, 8);
        return yyyy + "년 " + mm + "월 " + dd + "일";
    } else {
        return str;
    }
};

/**
 * 날짜 분리하여 리턴
 * @DESC : 20260610 -> {yyyy: "2026", mm: "06", dd:"10"}
 */
scwin.fn_getDateSplit = function (str) {
    let result = {
        yyyy: "",
        mm: "",
        dd: ""
    };

    if(str && str.length == 8) {
        let yyyy = str.substring(0, 4);
        let mm = str.substring(4, 6);
        let dd = str.substring(6, 8);
        result["yyyy"] = yyyy;
        result["mm"] = mm;
        result["dd"] = dd;
    }

    return result;
};

/**
 * 이메일포맷
 * @DESC : eds@krx.co.kr -> eds
 */
scwin.fn_emailFormat = function (str) {
    if(str) {
        let endIdx = str.indexOf('@');
        if(endIdx > -1) {
            str = str.substring(0, endIdx);
        }
    }
    return str;
};

/**
 * 이메일포맷 도메인
 * @DESC : eds@krx.co.kr -> @krx.co.kr
 */
scwin.fn_emailFormatDomain = function (str) {
    if(str) {
        let startIdx = str.indexOf('@')+1;
        str = str.substring(startIdx);
    }
    return str;
};

/**
 * 담당자 구분코드 세팅
 * @DESC : 재등록 가능한 경우만 필요
 */
scwin.fn_setChrgTp = function (idx) {
    let i = Number(idx) - 1;

    if(scwin.chrgTpCdArr[i]) {
        const chrgTpCd = scwin.chrgTpCdArr[i];
        dma_CorpDisclsChrgReq.set("chrgTpCd", chrgTpCd);
    }
};
